'use strict';
Catalogue.homeDefaults={
 announcement:'INDEPENDENT EXPRESSION. EVERYDAY UNIFORM.',
 heroEyebrow:'AF CULTURED / GROWING IN SILENCE',heroTitle:'GROWING\nIN\nSILENCE.',heroDescription:'No noise. Just growth.\nTwo colourways. One everyday statement.',heroButton:'SHOP THE DROP',heroImage:'assets/campaign-crew.jpg',heroAlt:'Three models wearing the AF CULTURED cream T-shirt at the street photoshoot',
 collectionTitle:'THE EVERYDAY\nUNIFORM.',collectionDescription:'Black & cream · RM79 each · S–XL',
 storyTitle:'LESS TALK.\nMORE GROWTH.',storyText:'Growing in Silence pairs a front logo with a statement back graphic. Explore both designs and see each T-shirt from the front and back.',storyImage:'assets/campaign-front-back.jpg',storyAlt:'AF CULTURED cream T-shirt worn front and back',
 campaignTitle:'OFF THE RACK.\nON THE STREET.',campaignDescription:'Growing in Silence, worn your way.\nSee the cream colourway in the real world.',
 gallery:[{image:'assets/campaign-crew.jpg',caption:'01 / THE CREW',alt:'Three models style the cream AF CULTURED T-shirt with jeans'},{image:'assets/campaign-front-back.jpg',caption:'02 / FRONT TO BACK',alt:'Two models showing the cream T-shirt front and back'},{image:'assets/campaign-street.jpg',caption:'03 / OWN YOUR PACE',alt:'Two models wearing AF CULTURED on outdoor steps'}],featuredIds:[]
};
Catalogue.home=function(data){return structuredClone({...this.homeDefaults,...data.homepage});};
const validateCatalogue=Catalogue.validate.bind(Catalogue);
Catalogue.validate=function(data){validateCatalogue(data);if(data.homepage!==undefined){const h=data.homepage;if(!h||typeof h!=='object'||Array.isArray(h))throw Error('Invalid homepage settings.');for(const [key,value] of Object.entries(this.homeDefaults)){if(!(key in h))throw Error('Missing homepage field: '+key);if(typeof value==='string'&&(typeof h[key]!=='string'||!h[key].trim()||h[key].length>2000))throw Error('Homepage fields must contain 1–2000 characters.');}for(const key of ['heroImage','storyImage'])if(!this.image(h[key]))throw Error('Upload a valid homepage photo.');if(!Array.isArray(h.gallery)||h.gallery.length>12||h.gallery.some(p=>!p||!this.image(p.image)||typeof p.caption!=='string'||p.caption.length>150||typeof p.alt!=='string'||!p.alt.trim()||p.alt.length>250))throw Error('Check campaign photos and descriptions (maximum 12).');if(!Array.isArray(h.featuredIds)||h.featuredIds.length>200||h.featuredIds.some(id=>typeof id!=='string')||new Set(h.featuredIds).size!==h.featuredIds.length)throw Error('Invalid featured products.');}return data;};
Catalogue.applyHomepage=function(data){const h=this.home(data);const set=(selector,value)=>{document.querySelector(selector).textContent=value;};set('.announcement',h.announcement);set('.hero-copy>.eyebrow',h.heroEyebrow);set('.hero h1',h.heroTitle);set('.hero-description',h.heroDescription);set('.hero-copy>.button',h.heroButton+' ↗');set('#collection h2',h.collectionTitle);set('#collection .section-heading>p',h.collectionDescription);set('.story-copy h2',h.storyTitle);set('.story-copy>p:not(.eyebrow)',h.storyText);const extra=document.querySelector('.story-copy>p:not(.eyebrow)+p');if(extra)extra.hidden=true;set('#campaign-title',h.campaignTitle);set('#campaign .section-heading>p',h.campaignDescription);for(const [selector,src,alt]of [['.hero-photo img',h.heroImage,h.heroAlt],['.story-image img',h.storyImage,h.storyAlt]]){const img=document.querySelector(selector);img.src=src;img.alt=alt;}document.querySelector('.campaign-grid').replaceChildren(...h.gallery.map(p=>{const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=p.image;img.alt=p.alt;img.loading='lazy';img.width=720;img.height=1080;caption.textContent=p.caption;figure.append(img,caption);return figure;}));document.querySelector('#campaign').hidden=h.gallery.length===0;};
